command:
$ErrorActionPreference='Stop'
$probe='C:\Users\james\.lmstudio\.forge-acl-probe-20260827T161200Z.tmp'
$expectedParent='C:\Users\james\.lmstudio'
try {
    New-Item -ItemType File -Path $probe -ErrorAction Stop | Out-Null
    $acl=Get-Acl -LiteralPath $probe
    Write-Output ('PROBE_PATH='+$probe)
    Write-Output ('OWNER='+$acl.Owner)
    Write-Output ('GROUP='+$acl.Group)
    Write-Output ('SDDL='+$acl.Sddl)
}
finally {
    if(Test-Path -LiteralPath $probe) {
        $actualParent=[IO.Path]::GetFullPath((Split-Path -Parent $probe))
        $leaf=Split-Path -Leaf $probe
        if(-not [string]::Equals($actualParent,$expectedParent,[StringComparison]::OrdinalIgnoreCase)-or -not $leaf.StartsWith('.forge-acl-probe-',[StringComparison]::Ordinal)){throw 'ACL probe cleanup target validation failed.'}
        Remove-Item -LiteralPath $probe
    }
}
